DROP TABLE IF EXISTS `ngos`;
CREATE TABLE `ngos` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int DEFAULT NULL,
  `organization_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `registration_number` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `cause_area` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `target_amount` decimal(12,2) DEFAULT '100000.00',
  `raised_amount` decimal(12,2) DEFAULT '0.00',
  `verified_by_admin` tinyint(1) DEFAULT '1',
  `website` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `image_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `address` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `contact_person` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `phone` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `latitude` decimal(10,8) DEFAULT '28.61390000',
  `longitude` decimal(11,8) DEFAULT '77.20900000',
  `city` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT 'New Delhi',
  `state` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT 'Delhi',
  `accepted_categories` json DEFAULT NULL,
  `supporting_documents` json DEFAULT NULL,
  `capacity_limit` int DEFAULT '1000',
  `current_load` int DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `registration_number` (`registration_number`),
  KEY `user_id` (`user_id`),
  KEY `idx_ngo_cause` (`cause_area`),
  CONSTRAINT `ngos_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `ngos` (`id`, `user_id`, `organization_name`, `registration_number`, `cause_area`, `description`, `target_amount`, `raised_amount`, `verified_by_admin`, `website`, `image_url`, `address`, `created_at`, `contact_person`, `phone`, `latitude`, `longitude`, `city`, `state`, `accepted_categories`, `supporting_documents`, `capacity_limit`, `current_load`) VALUES (1, 4, 'Pratham Shiksha Foundation', 'NGO-DEL-2018-88741', 'Child Education', 'Dedicated to providing high-quality primary education, digital literacy, and free midday nutrition to over 12,000 underprivileged children in rural and urban slums.', '500000.00', '351000.00', 1, 'https://prathamshiksha.org', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?auto=format&fit=crop&w=600&q=80', 'Plot 42, Sector 14, New Delhi - 110025', '2026-11-19 16:21:44', 'Dr. Sunita Deshmukh', '+91 9877001122', '28.61390000', '77.20900000', 'New Delhi', 'Delhi', '["Books","Stationery","Toys","Clothes"]', NULL, 2500, 350);
INSERT INTO `ngos` (`id`, `user_id`, `organization_name`, `registration_number`, `cause_area`, `description`, `target_amount`, `raised_amount`, `verified_by_admin`, `website`, `image_url`, `address`, `created_at`, `contact_person`, `phone`, `latitude`, `longitude`, `city`, `state`, `accepted_categories`, `supporting_documents`, `capacity_limit`, `current_load`) VALUES (2, NULL, 'Annam Hunger Relief Trust', 'NGO-MUM-2020-55129', 'Hunger & Nutrition', 'Operating community kitchens and food distribution vans that serve over 5,000 hot wholesome meals daily to hospital patients and daily wage earners.', '750000.00', '589000.00', 1, 'https://annamrelief.org', 'https://images.unsplash.com/photo-1488521787991-ed7bbaae773c?auto=format&fit=crop&w=600&q=80', '22 Bandra Reclamation, Mumbai - 400050', '2026-11-19 16:21:44', 'Rajesh Mehra', '+91 9822114455', '19.07600000', '72.87770000', 'Mumbai', 'Maharashtra', '["Food","Household essentials","Blankets"]', NULL, 3000, 620);
INSERT INTO `ngos` (`id`, `user_id`, `organization_name`, `registration_number`, `cause_area`, `description`, `target_amount`, `raised_amount`, `verified_by_admin`, `website`, `image_url`, `address`, `created_at`, `contact_person`, `phone`, `latitude`, `longitude`, `city`, `state`, `accepted_categories`, `supporting_documents`, `capacity_limit`, `current_load`) VALUES (3, NULL, 'Vriksha Dharini Greening Mission', 'NGO-BLR-2021-33419', 'Environment & Forestry', 'Restoring degraded native forest lands through community Miyawaki planting. Planted and nurtured over 150,000 native tree saplings across Karnataka and Maharashtra.', '300000.00', '215000.00', 1, 'https://vrikshadharini.org', 'https://images.unsplash.com/photo-1542601906990-b4d3fb778b09?auto=format&fit=crop&w=600&q=80', '15 Indiranagar, Bengaluru - 560038', '2026-11-19 16:21:44', 'Ananya Rao', '+91 9844332211', '12.97160000', '77.59460000', 'Bengaluru', 'Karnataka', '["Household essentials","Books"]', NULL, 1200, 180);
INSERT INTO `ngos` (`id`, `user_id`, `organization_name`, `registration_number`, `cause_area`, `description`, `target_amount`, `raised_amount`, `verified_by_admin`, `website`, `image_url`, `address`, `created_at`, `contact_person`, `phone`, `latitude`, `longitude`, `city`, `state`, `accepted_categories`, `supporting_documents`, `capacity_limit`, `current_load`) VALUES (4, NULL, 'Mahila Shakti Artisan Collective', 'NGO-RAJ-2019-11234', 'Women Empowerment', 'Skilling rural women in handloom weaving, block printing, and micro-entrepreneurship, directly empowering 2,400 rural families with dignified livelihoods.', '400000.00', '310000.00', 1, 'https://mahilashakti.org', 'https://images.unsplash.com/photo-1509099836639-18ba1795216d?auto=format&fit=crop&w=600&q=80', 'B-8 Gandhi Path, Jaipur, Rajasthan - 302021', '2026-11-19 16:21:44', 'Meenakshi Rathore', '+91 9829001144', '26.91240000', '75.78730000', 'Jaipur', 'Rajasthan', '["Clothes","Blankets","Shoes","Household essentials"]', NULL, 1800, 410);
INSERT INTO `ngos` (`id`, `user_id`, `organization_name`, `registration_number`, `cause_area`, `description`, `target_amount`, `raised_amount`, `verified_by_admin`, `website`, `image_url`, `address`, `created_at`, `contact_person`, `phone`, `latitude`, `longitude`, `city`, `state`, `accepted_categories`, `supporting_documents`, `capacity_limit`, `current_load`) VALUES (5, NULL, 'Samarpan Child & Community Trust', 'NGO-DEL-2022-77441', 'Child Welfare & Education', 'Providing primary education, winter clothing kits, nutritional meal packages, and recreation toys to over 3,500 children across Delhi NCR slums.', '600000.00', '415000.00', 1, 'https://samarpanchildtrust.org', 'https://images.unsplash.com/photo-1488521787991-ed7bbaae773c?auto=format&fit=crop&w=600&q=80', 'B-14 Sector 62, Noida, NCR Delhi - 201301', '2026-11-19 16:43:45', 'Sunil Kumar Verma', '+91 9810224466', '28.53550000', '77.39100000', 'Noida', 'Uttar Pradesh', '["Books","Clothes","Shoes","Toys","Blankets","Stationery","Food","Household essentials"]', NULL, 2000, 280);

DROP TABLE IF EXISTS `notifications`;
CREATE TABLE `notifications` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `message` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` enum('donation','delivery','reward','order','system') COLLATE utf8mb4_unicode_ci DEFAULT 'system',
  `reference_id` int DEFAULT NULL,
  `reference_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_read` tinyint(1) DEFAULT '0',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `notifications_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=80 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `notifications` (`id`, `user_id`, `title`, `message`, `type`, `reference_id`, `reference_type`, `is_read`, `created_at`) VALUES (1, 1, 'Admin System Ready', 'Phase 4 Complete: Full platform analytics, NGO verification, and delivery monitoring active.', 'system', NULL, NULL, 0, '2026-11-19 17:17:57');
