DROP TABLE IF EXISTS `products`;
CREATE TABLE `products` (
  `id` int NOT NULL AUTO_INCREMENT,
  `seller_id` int NOT NULL,
  `category_id` int NOT NULL,
  `name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(250) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `price` decimal(10,2) NOT NULL,
  `stock` int NOT NULL DEFAULT '0',
  `image_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT '1',
  `donation_percentage` int DEFAULT '5',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_product_seller` (`seller_id`),
  KEY `idx_product_category` (`category_id`),
  KEY `idx_product_active` (`is_active`),
  CONSTRAINT `products_ibfk_1` FOREIGN KEY (`seller_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `products_ibfk_2` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `products` (`id`, `seller_id`, `category_id`, `name`, `slug`, `description`, `price`, `stock`, `image_url`, `is_active`, `donation_percentage`, `created_at`, `updated_at`) VALUES (1, 2, 1, 'Pure Khadi Hand-Spun Kurta', 'pure-khadi-hand-spun-kurta', 'Ethically crafted 100% breathable organic hand-spun Khadi cotton kurta by women weavers in Wardha. Includes natural coconut shell buttons.', '899.00', 36, 'https://images.unsplash.com/photo-1596755094514-f87e34085b2c?auto=format&fit=crop&w=600&q=80', 1, 10, '2026-11-19 16:21:44', '2026-11-19 17:38:06');
INSERT INTO `products` (`id`, `seller_id`, `category_id`, `name`, `slug`, `description`, `price`, `stock`, `image_url`, `is_active`, `donation_percentage`, `created_at`, `updated_at`) VALUES (2, 2, 2, 'Raw Forest Wild Honey (500g)', 'raw-forest-wild-honey-500g', 'Unfiltered, unpasteurized natural honey sustainably harvested by tribal beekeepers in the Nilgiri biosphere. Rich in trace minerals and antioxidants.', '450.00', 58, 'https://images.unsplash.com/photo-1587049352846-4a222e784d38?auto=format&fit=crop&w=600&q=80', 1, 8, '2026-11-19 16:21:44', '2026-11-19 16:26:44');
INSERT INTO `products` (`id`, `seller_id`, `category_id`, `name`, `slug`, `description`, `price`, `stock`, `image_url`, `is_active`, `donation_percentage`, `created_at`, `updated_at`) VALUES (3, 2, 3, 'Handcrafted Terracotta Water Carafe with Cup', 'handcrafted-terracotta-water-carafe', 'Traditional alkaline red clay jug that naturally cools drinking water and balances body pH. Hand-molded by master potters of Rajasthan.', '599.00', 30, 'https://images.unsplash.com/photo-1615485290382-441e4d049cb5?auto=format&fit=crop&w=600&q=80', 1, 12, '2026-11-19 16:21:44', '2026-11-19 16:21:44');
INSERT INTO `products` (`id`, `seller_id`, `category_id`, `name`, `slug`, `description`, `price`, `stock`, `image_url`, `is_active`, `donation_percentage`, `created_at`, `updated_at`) VALUES (4, 2, 4, 'Plantable Seed Pens & Notebook Pack', 'plantable-seed-pens-notebook-pack', 'Contains 5 recycled paper seed pens (tomato, marigold, basil) and 1 tree-free handmade cotton paper notebook. Plant the caps after use!', '299.00', 120, 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?auto=format&fit=crop&w=600&q=80', 1, 15, '2026-11-19 16:21:44', '2026-11-19 16:21:44');
INSERT INTO `products` (`id`, `seller_id`, `category_id`, `name`, `slug`, `description`, `price`, `stock`, `image_url`, `is_active`, `donation_percentage`, `created_at`, `updated_at`) VALUES (5, 2, 5, 'Essential Social Care & Nutrition Family Kit', 'essential-social-care-nutrition-kit', 'A comprehensive donation-ready package containing fortified lentils, cold-pressed cooking oil, jaggery, antibacterial soaps, and sanitary essentials for a family of 4.', '1199.00', 50, 'https://images.unsplash.com/photo-1593113598332-cd288d649433?auto=format&fit=crop&w=600&q=80', 1, 20, '2026-11-19 16:21:44', '2026-11-19 16:21:44');
INSERT INTO `products` (`id`, `seller_id`, `category_id`, `name`, `slug`, `description`, `price`, `stock`, `image_url`, `is_active`, `donation_percentage`, `created_at`, `updated_at`) VALUES (6, 2, 2, 'Cold-Pressed Virgin Mustard Oil (1 Litre)', 'cold-pressed-virgin-mustard-oil-1l', 'Traditional wooden kachi ghani extracted mustard oil from organically grown seeds without any heat processing or chemical bleaching.', '260.00', 80, 'https://images.unsplash.com/photo-1474979266404-7eaacbcd87c5?auto=format&fit=crop&w=600&q=80', 1, 5, '2026-11-19 16:21:44', '2026-11-19 16:21:44');
INSERT INTO `products` (`id`, `seller_id`, `category_id`, `name`, `slug`, `description`, `price`, `stock`, `image_url`, `is_active`, `donation_percentage`, `created_at`, `updated_at`) VALUES (7, 2, 3, 'Handwoven Bamboo Desk Organizer & Planter', 'handwoven-bamboo-desk-organizer', 'Sturdy eco-friendly desk accessory woven by tribal artisans in Assam. Perfect for holding stationery and small indoor succulents.', '380.00', 40, 'https://images.unsplash.com/photo-1591129841117-3adfd313e34f?auto=format&fit=crop&w=600&q=80', 1, 10, '2026-11-19 16:21:44', '2026-11-19 16:21:44');
INSERT INTO `products` (`id`, `seller_id`, `category_id`, `name`, `slug`, `description`, `price`, `stock`, `image_url`, `is_active`, `donation_percentage`, `created_at`, `updated_at`) VALUES (8, 2, 1, 'Artisan Pashmina Wool Shawl', 'artisan-pashmina-wool-shawl', 'Luxuriously soft hand-spun fine wool shawl with delicate border needlework from Kashmiri weavers.', '2499.00', 15, 'https://images.unsplash.com/photo-1608256246200-53e635b5b65f?auto=format&fit=crop&w=600&q=80', 1, 10, '2026-11-19 16:21:44', '2026-11-19 16:21:44');

DROP TABLE IF EXISTS `reward_rules`;
